var HIGH_VALUE_RE = /plumb|electric|roof|hvac|air.?con|concret|landscap|build|renovat|paint|tile|fenc|pest|solar|dentist|dental|physio|chiro|law|legal|account|mortgage|broker|mechanic|auto|towing|removal|clean/i;
