function computeBuyScore(input) {
  let score = 0;
  const kind = classifyWebsite(input.website);
  const status = (input.websiteStatus ?? "").toLowerCase();
  if (kind === "none") {
    score += 35;
  } else if (kind === "social") {
    score += 28;
  } else if (status === "dead" || status === "parked") {
    score += 30;
  } else if (status === "thirdparty") {
    score += 28;
  } else if (status === "outdated") {
    score += 20;
  } else if (status === "slow") {
    score += 15;
  } else if (status === "ok") {
    score += 0;
  } else {
    score += 5;
  }
  if (input.hasViewport === false) score += 7;
  const rating = input.rating ?? 0;
  const reviews = input.reviewCount ?? 0;
  if (rating >= 4.3 && reviews >= 20) score += 10;
  else if (rating >= 4 && reviews >= 10) score += 6;
  if (reviews >= 5 && reviews <= 50) score += 8;
  else if (reviews > 50) score += 4;
  if (input.phoneIsMobile === true) score += 8;
  const cat = input.category ?? "";
  if (HIGH_VALUE_RE.test(cat)) score += 12;
  else if (MID_VALUE_RE.test(cat)) score += 6;
  if (rating > 0 && rating < 3.5 && reviews >= 5) score -= 10;
  return Math.max(0, Math.min(100, Math.round(score)));
}

